class PrivateLotTemplateAlgorithm(QCAlgorithm):

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = [
            self.add_equity("SPY", Resolution.DAILY).symbol,
            self.add_equity("AAPL", Resolution.DAILY).symbol,
            self.add_equity("IBM", Resolution.DAILY).symbol,
            self.add_equity("BAC", Resolution.DAILY).symbol,
            self.add_equity("AIG", Resolution.DAILY).symbol
        ]

        self.spy = self.symbols[0]
        self.aapl = self.symbols[1]

        self.closes = {symbol: deque(maxlen=101) for symbol in self.symbols}
        self.previous_closes = {symbol: None for symbol in self.symbols}

        self.aapl_red_streak = 0
        self.rsi_period = 14
        self.rsi_count = 0
        self.rsi_gain_sum = 0.0
        self.rsi_loss_sum = 0.0
        self.rsi_avg_gain = None
        self.rsi_avg_loss = None
        self.aapl_rsi = None

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def on_data(self, data: Slice):
        if any(not data.bars.contains_key(symbol) for symbol in self.symbols):
            return

        bars = {symbol: data.bars[symbol] for symbol in self.symbols}

        for symbol in self.symbols:
            self.closes[symbol].append(float(bars[symbol].close))

        aapl_close = float(bars[self.aapl].close)
        aapl_open = float(bars[self.aapl].open)
        previous_aapl_close = self.previous_closes[self.aapl]

        if aapl_close < aapl_open:
            self.aapl_red_streak += 1
        else:
            self.aapl_red_streak = 0

        if previous_aapl_close is not None:
            change = aapl_close - previous_aapl_close
            gain = max(change, 0.0)
            loss = max(-change, 0.0)

            if self.rsi_count < self.rsi_period:
                self.rsi_gain_sum += gain
                self.rsi_loss_sum += loss
                self.rsi_count += 1

                if self.rsi_count == self.rsi_period:
                    self.rsi_avg_gain = self.rsi_gain_sum / self.rsi_period
                    self.rsi_avg_loss = self.rsi_loss_sum / self.rsi_period
                    self.aapl_rsi = self._calculate_rsi()
            else:
                self.rsi_avg_gain = (
                    (self.rsi_avg_gain * (self.rsi_period - 1)) + gain
                ) / self.rsi_period
                self.rsi_avg_loss = (
                    (self.rsi_avg_loss * (self.rsi_period - 1)) + loss
                ) / self.rsi_period
                self.aapl_rsi = self._calculate_rsi()

        spy_history = self.closes[self.spy]
        indicators_ready = len(spy_history) == 101 and self.aapl_rsi is not None

        if indicators_ready:
            spy_close = float(bars[self.spy].close)
            yesterday_spy_close = spy_history[-2]
            yesterday_sma_100 = sum(list(spy_history)[:-1]) / 100.0
            today_sma_100 = sum(list(spy_history)[-100:]) / 100.0

            spy_crosses_above = (
                yesterday_spy_close <= yesterday_sma_100
                and spy_close > today_sma_100
            )
            spy_crosses_below = (
                yesterday_spy_close >= yesterday_sma_100
                and spy_close < today_sma_100
            )

            # Sells are evaluated before buys.
            if self.strategy_a_lot > 0 and spy_crosses_below:
                self.market_order(self.spy, -self.strategy_a_lot)
                self.strategy_a_lot = 0

            if self.strategy_b_lot > 0 and self.aapl_rsi > 60:
                self.market_order(self.aapl, -self.strategy_b_lot)
                self.strategy_b_lot = 0

            if self.strategy_a_lot == 0 and spy_crosses_above:
                quantity = int((self.portfolio.total_portfolio_value * 0.40) / spy_close)
                if quantity > 0:
                    self.market_order(self.spy, quantity)
                    self.strategy_a_lot = quantity

            if self.strategy_b_lot == 0 and self.aapl_red_streak >= 3:
                if self.portfolio.cash >= 20_000:
                    quantity = int(20_000 / aapl_close)
                    if quantity > 0:
                        self.market_order(self.aapl, quantity)
                        self.strategy_b_lot = quantity

        for symbol in self.symbols:
            self.previous_closes[symbol] = float(bars[symbol].close)

    def _calculate_rsi(self):
        if self.rsi_avg_loss == 0:
            return 100.0
        if self.rsi_avg_gain == 0:
            return 0.0

        rs = self.rsi_avg_gain / self.rsi_avg_loss
        return 100.0 - (100.0 / (1.0 + rs))
