from collections import deque
from AlgorithmImports import *


class IndependentDailyStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_closes = deque(maxlen=101)
        self.aapl_closes = deque(maxlen=15)

        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.rsi_seed_changes = []
        self.rsi_average_gain = None
        self.rsi_average_loss = None
        self.aapl_rsi = None

        self.lots = {
            "A": {"symbol": self.spy, "quantity": 0, "pending": False},
            "B": {"symbol": self.aapl, "quantity": 0, "pending": False}
        }
        self.order_to_lot = {}

    def OnData(self, data):
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bar = data.Bars[symbol]

                if symbol == self.spy:
                    self.spy_closes.append(bar.Close)

                elif symbol == self.aapl:
                    self._update_aapl_state(bar)

        if not all(data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        spy_bar = data.Bars[self.spy]
        aapl_bar = data.Bars[self.aapl]

        # Sells are evaluated before buys.
        self._evaluate_strategy_a_sell()
        self._evaluate_strategy_b_sell()

        self._evaluate_strategy_a_buy(spy_bar.Close)
        self._evaluate_strategy_b_buy(aapl_bar.Close)

    def _update_aapl_state(self, bar):
        close = bar.Close

        if close < bar.Open:
            self.aapl_red_streak += 1
        else:
            self.aapl_red_streak = 0

        if self.aapl_previous_close is not None:
            change = close - self.aapl_previous_close
            gain = max(change, 0)
            loss = max(-change, 0)

            if self.rsi_average_gain is None:
                self.rsi_seed_changes.append((gain, loss))
                if len(self.rsi_seed_changes) == 14:
                    self.rsi_average_gain = sum(x[0] for x in self.rsi_seed_changes) / 14.0
                    self.rsi_average_loss = sum(x[1] for x in self.rsi_seed_changes) / 14.0
                    self.aapl_rsi = self._calculate_rsi()
            else:
                self.rsi_average_gain = (self.rsi_average_gain * 13 + gain) / 14.0
                self.rsi_average_loss = (self.rsi_average_loss * 13 + loss) / 14.0
                self.aapl_rsi = self._calculate_rsi()

        self.aapl_previous_close = close
        self.aapl_closes.append(close)

    def _calculate_rsi(self):
        if self.rsi_average_loss == 0:
            return 100.0
        if self.rsi_average_gain == 0:
            return 0.0
        rs = self.rsi_average_gain / self.rsi_average_loss
        return 100.0 - (100.0 / (1.0 + rs))

    def _evaluate_strategy_a_sell(self):
        lot = self.lots["A"]
        if lot["quantity"] <= 0 or lot["pending"] or len(self.spy_closes) < 101:
            return

        closes = list(self.spy_closes)
        yesterday_close = closes[-2]
        today_close = closes[-1]
        yesterday_sma = sum(closes[:-1]) / 100.0
        today_sma = sum(closes[-100:]) / 100.0

        if yesterday_close >= yesterday_sma and today_close < today_sma:
            self._place_order("A", -lot["quantity"])

    def _evaluate_strategy_b_sell(self):
        lot = self.lots["B"]
        if lot["quantity"] <= 0 or lot["pending"] or self.aapl_rsi is None:
            return

        if self.aapl_rsi > 60:
            self._place_order("B", -lot["quantity"])

    def _evaluate_strategy_a_buy(self, close):
        lot = self.lots["A"]
        if lot["quantity"] > 0 or lot["pending"] or len(self.spy_closes) < 101:
            return

        closes = list(self.spy_closes)
        yesterday_close = closes[-2]
        today_close = closes[-1]
        yesterday_sma = sum(closes[:-1]) / 100.0
        today_sma = sum(closes[-100:]) / 100.0

        if yesterday_close <= yesterday_sma and today_close > today_sma:
            quantity = int((self.Portfolio.TotalPortfolioValue * 0.40) / close)
            if quantity > 0:
                self._place_order("A", quantity)

    def _evaluate_strategy_b_buy(self, close):
        lot = self.lots["B"]
        if lot["quantity"] > 0 or lot["pending"]:
            return

        if self.aapl_red_streak >= 3 and self.Portfolio.Cash >= 20000:
            quantity = int(20000 / close)
            if quantity > 0:
                self._place_order("B", quantity)

    def _place_order(self, lot_name, quantity):
        lot = self.lots[lot_name]
        ticket = self.MarketOrder(lot["symbol"], quantity, tag=lot_name)
        lot["pending"] = True
        self.order_to_lot[ticket.OrderId] = lot_name

    def OnOrderEvent(self, order_event):
        if order_event.OrderId not in self.order_to_lot:
            return

        lot_name = self.order_to_lot[order_event.OrderId]
        lot = self.lots[lot_name]

        if order_event.FillQuantity != 0:
            lot["quantity"] += order_event.FillQuantity
            if lot["quantity"] < 0:
                lot["quantity"] = 0

        if order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
            lot["pending"] = False
            del self.order_to_lot[order_event.OrderId]
